# GitHub Issues Progress Monitoring
# Script para acompanhar progresso das issues criadas

Param(\n    [string]$Format = \"table\", # table, json, summary\n    [switch]$OnlyOpen,\n    [string]$Priority = \"\", # P1, P2, P3\n    [switch]$Assignees\n)\n\nfunction Get-IssueProgress {\n    Write-Host \"\ud83d\udcca Fetching GitHub Issues progress...\" -ForegroundColor Cyan\n    \n    # Build gh command\n    $cmd = @(\"issue\", \"list\", \"--json\", \"number,title,state,labels,assignees,createdAt,updatedAt,comments\")\n    \n    if ($OnlyOpen) {\n        $cmd += \"--state\", \"open\"\n    }\n    \n    if ($Priority) {\n        $cmd += \"--label\", \"$Priority-*\"\n    }\n    \n    try {\n        $issues = gh @cmd | ConvertFrom-Json\n        return $issues\n    } catch {\n        Write-Host \"\u274c Error fetching issues: $_\" -ForegroundColor Red\n        return @()\n    }\n}\n\nfunction Format-IssueTable {\n    param([array]$Issues)\n    \n    if ($Issues.Count -eq 0) {\n        Write-Host \"\u26a0\ufe0f  No issues found matching criteria\" -ForegroundColor Yellow\n        return\n    }\n    \n    Write-Host \"\"\n    Write-Host \"=== GitHub Issues Overview ===\" -ForegroundColor Green\n    \n    $Issues | ForEach-Object {\n        $priority = ($_.labels | Where-Object { $_.name -match \"P[123]\" } | Select-Object -First 1).name\n        $assignee = if ($_.assignees.Count -gt 0) { $_.assignees[0].login } else { \"Unassigned\" }\n        $status = if ($_.state -eq \"closed\") { \"\u2705\" } else { \"\ud83d\udd04\" }\n        $commentCount = $_.comments\n        \n        Write-Host \"$status #$($_.number) [$priority] $($_.title)\" -ForegroundColor White\n        Write-Host \"   Assignee: $assignee | Comments: $commentCount | Updated: $($_.updatedAt.Substring(0,10))\" -ForegroundColor Gray\n        Write-Host \"\"\n    }\n}\n\nfunction Format-IssueSummary {\n    param([array]$Issues)\n    \n    if ($Issues.Count -eq 0) {\n        Write-Host \"\u26a0\ufe0f  No issues found\" -ForegroundColor Yellow\n        return\n    }\n    \n    # Statistics\n    $total = $Issues.Count\n    $open = ($Issues | Where-Object { $_.state -eq \"open\" }).Count\n    $closed = ($Issues | Where-Object { $_.state -eq \"closed\" }).Count\n    \n    $p1Count = ($Issues | Where-Object { ($_.labels.name -contains \"P1-high\") }).Count\n    $p2Count = ($Issues | Where-Object { ($_.labels.name -contains \"P2-medium\") }).Count\n    $p3Count = ($Issues | Where-Object { ($_.labels.name -contains \"P3-low\") }).Count\n    \n    $assigned = ($Issues | Where-Object { $_.assignees.Count -gt 0 }).Count\n    $unassigned = ($Issues | Where-Object { $_.assignees.Count -eq 0 }).Count\n    \n    Write-Host \"\"\n    Write-Host \"=== Issues Summary ===\" -ForegroundColor Green\n    Write-Host \"\ud83d\udcca Total Issues: $total\" -ForegroundColor White\n    Write-Host \"   \ud83d\udd04 Open: $open\" -ForegroundColor Yellow\n    Write-Host \"   \u2705 Closed: $closed\" -ForegroundColor Green\n    Write-Host \"\"\n    Write-Host \"\ud83c\udff7\ufe0f  Priority Breakdown:\" -ForegroundColor White\n    Write-Host \"   \ud83d\udd34 P1 (High): $p1Count\" -ForegroundColor Red\n    Write-Host \"   \ud83d\udfe1 P2 (Medium): $p2Count\" -ForegroundColor Yellow\n    Write-Host \"   \ud83d\udfe2 P3 (Low): $p3Count\" -ForegroundColor Green\n    Write-Host \"\"\n    Write-Host \"\ud83d\udc65 Assignment Status:\" -ForegroundColor White\n    Write-Host \"   \u2705 Assigned: $assigned\" -ForegroundColor Green\n    Write-Host \"   \ud83d\udd04 Unassigned: $unassigned\" -ForegroundColor Yellow\n    \n    # Progress percentage\n    if ($total -gt 0) {\n        $progressPercentage = [math]::Round(($closed / $total) * 100, 1)\n        Write-Host \"\"\n        Write-Host \"\ud83c\udfc6 Overall Progress: $progressPercentage% ($closed/$total completed)\" -ForegroundColor Cyan\n    }\n}\n\nfunction Show-AssigneeBreakdown {\n    param([array]$Issues)\n    \n    Write-Host \"\"\n    Write-Host \"=== Assignee Breakdown ===\" -ForegroundColor Green\n    \n    # Group by assignee\n    $assigneeGroups = $Issues | Group-Object { \n        if ($_.assignees.Count -gt 0) { \n            $_.assignees[0].login \n        } else { \n            \"Unassigned\" \n        }\n    }\n    \n    foreach ($group in $assigneeGroups | Sort-Object Name) {\n        $assigneeName = $group.Name\n        $assigneeIssues = $group.Group\n        $openCount = ($assigneeIssues | Where-Object { $_.state -eq \"open\" }).Count\n        $closedCount = ($assigneeIssues | Where-Object { $_.state -eq \"closed\" }).Count\n        $total = $assigneeIssues.Count\n        \n        $progressPercentage = if ($total -gt 0) { \n            [math]::Round(($closedCount / $total) * 100, 1) \n        } else { \n            0 \n        }\n        \n        Write-Host \"\ud83d\udc64 $assigneeName\" -ForegroundColor White\n        Write-Host \"   Total: $total | Open: $openCount | Closed: $closedCount | Progress: $progressPercentage%\" -ForegroundColor Gray\n        \n        # List issues for this assignee\n        $assigneeIssues | ForEach-Object {\n            $status = if ($_.state -eq \"closed\") { \"\u2705\" } else { \"\ud83d\udd04\" }\n            $priority = ($_.labels | Where-Object { $_.name -match \"P[123]\" } | Select-Object -First 1).name\n            Write-Host \"     $status #$($_.number) [$priority] $($_.title)\" -ForegroundColor Gray\n        }\n        \n        Write-Host \"\"\n    }\n}\n\nfunction Show-Commands {\n    Write-Host \"\"\n    Write-Host \"=== Quick Commands ===\" -ForegroundColor Cyan\n    Write-Host \"\ud83d\udd0d Useful GitHub CLI commands:\" -ForegroundColor White\n    Write-Host \"   gh issue list                    # List all issues\" -ForegroundColor Gray\n    Write-Host \"   gh issue view <number>           # View specific issue\" -ForegroundColor Gray\n    Write-Host \"   gh issue list --assignee @me     # Your assigned issues\" -ForegroundColor Gray\n    Write-Host \"   gh issue list --label P1-high    # High priority issues\" -ForegroundColor Gray\n    Write-Host \"   gh issue close <number>          # Close completed issue\" -ForegroundColor Gray\n    Write-Host \"   gh issue comment <number>        # Add progress comment\" -ForegroundColor Gray\n    Write-Host \"\"\n    Write-Host \"\ud83d\udccb Monitoring:\" -ForegroundColor White\n    Write-Host \"   .\\github\\issues\\progress.ps1                      # This script (table view)\" -ForegroundColor Gray\n    Write-Host \"   .\\github\\issues\\progress.ps1 -Assignees          # By assignee\" -ForegroundColor Gray\n    Write-Host \"   .\\github\\issues\\progress.ps1 -Priority P1        # Only P1 issues\" -ForegroundColor Gray\n    Write-Host \"   .\\github\\issues\\progress.ps1 -Format summary     # Summary stats\" -ForegroundColor Gray\n}\n\n# Main execution\nWrite-Host \"\ud83d\ude80 Tracking GO Issues Progress Monitor\" -ForegroundColor Cyan\nWrite-Host \"Generated on $(Get-Date -Format 'yyyy-MM-dd HH:mm')\" -ForegroundColor Gray\n\n# Check prerequisites\nif (-not (Get-Command gh -ErrorAction SilentlyContinue)) {\n    Write-Host \"\u274c GitHub CLI not found. Install from https://cli.github.com/\" -ForegroundColor Red\n    exit 1\n}\n\ntry {\n    $authStatus = gh auth status 2>&1\n    if ($LASTEXITCODE -ne 0) {\n        Write-Host \"\u274c GitHub CLI not authenticated. Run: gh auth login\" -ForegroundColor Red\n        exit 1\n    }\n} catch {\n    Write-Host \"\u274c GitHub CLI authentication failed\" -ForegroundColor Red\n    exit 1\n}\n\n# Fetch and display issues\n$issues = Get-IssueProgress\n\nswitch ($Format) {\n    \"table\" { Format-IssueTable $issues }\n    \"summary\" { Format-IssueSummary $issues }\n    \"json\" { $issues | ConvertTo-Json -Depth 3 }\n    default { Format-IssueTable $issues }\n}\n\nif ($Assignees) {\n    Show-AssigneeBreakdown $issues\n}\n\nShow-Commands